-- PME-1: evaluation campaign, portfolio discriminator, Hybrid attribution, drop PaperDryRun.
--
-- Prisma is the single source of schema truth; this migration is hand-authored
-- because it interleaves a data backfill between additive and non-null steps
-- (create parent -> backfill children -> tighten constraints), which the
-- autogenerated migration cannot express. No behaviour change: the application
-- code moves its kill-switch reads to the parent, but the semantics are identical.

-- CreateEnum
CREATE TYPE "PaperPortfolio" AS ENUM ('baseline', 'simulation', 'hybrid');

-- CreateTable: the parent campaign.
CREATE TABLE "paper_evaluation_campaigns" (
    "id" TEXT NOT NULL,
    "label" TEXT,
    "starting_bankroll_cents" INTEGER NOT NULL,
    "withdrawal_ceiling_multiple" DECIMAL(4,2) NOT NULL,
    "continuous_evaluation_enabled" BOOLEAN NOT NULL DEFAULT false,
    "kill_switch_engaged" BOOLEAN NOT NULL DEFAULT false,
    "campaign_started_at" TIMESTAMP(3) NOT NULL,
    "active_config_changed_at" TIMESTAMP(3),
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "paper_evaluation_campaigns_pkey" PRIMARY KEY ("id")
);

-- Step 2 (additive): the portfolio discriminator columns land nullable so the
-- backfill can populate them before they are tightened.
ALTER TABLE "paper_campaigns"
    ADD COLUMN "evaluation_campaign_id" TEXT,
    ADD COLUMN "portfolio" "PaperPortfolio",
    ADD COLUMN "portfolio_started_at" TIMESTAMP(3);

-- Hybrid attribution columns (D6).
ALTER TABLE "paper_positions" ADD COLUMN "source_model_version" TEXT;
ALTER TABLE "paper_cycle_candidates" ADD COLUMN "source_model_version" TEXT;

-- Step 3 (backfill): promote every existing PaperCampaign to a portfolio within a
-- new parent evaluation campaign. Exactly one campaign is expected in dev/prod;
-- the DO block is written to be safe for zero rows and correct for one.
DO $$
DECLARE
    c RECORD;
    parent_id TEXT;
    resolved_portfolio "PaperPortfolio";
    resolved_ceiling DECIMAL(4,2);
    sim_stat_count INTEGER;
    base_stat_count INTEGER;
    distinct_versions INTEGER;
BEGIN
    FOR c IN SELECT * FROM "paper_campaigns" WHERE "evaluation_campaign_id" IS NULL LOOP
        -- Withdrawal ceiling comes from the active (latest) risk config; fall back
        -- to the product default (10.00) if no config exists yet.
        SELECT "withdrawal_ceiling_multiple"
          INTO resolved_ceiling
          FROM "paper_risk_configs"
         WHERE "campaign_id" = c."id"
      ORDER BY "effective_from" DESC
         LIMIT 1;
        IF resolved_ceiling IS NULL THEN
            resolved_ceiling := 10.00;
        END IF;

        -- Determine the portfolio matching the currently-active configuration.
        -- Mixed selection -> hybrid; otherwise the dominant single engine; default
        -- baseline when ambiguous or when no selection exists.
        SELECT count(DISTINCT "model_version") INTO distinct_versions FROM "model_selections";
        SELECT count(*) INTO sim_stat_count FROM "model_selections" WHERE "model_version" LIKE 'simulation-%';
        SELECT count(*) INTO base_stat_count FROM "model_selections" WHERE "model_version" NOT LIKE 'simulation-%';

        IF distinct_versions > 1 THEN
            resolved_portfolio := 'hybrid';
        ELSIF sim_stat_count > 0 AND base_stat_count = 0 THEN
            resolved_portfolio := 'simulation';
        ELSE
            resolved_portfolio := 'baseline';
        END IF;

        parent_id := gen_random_uuid()::text;
        INSERT INTO "paper_evaluation_campaigns" (
            "id", "label", "starting_bankroll_cents", "withdrawal_ceiling_multiple",
            "continuous_evaluation_enabled", "kill_switch_engaged",
            "campaign_started_at", "active_config_changed_at", "created_at", "updated_at"
        ) VALUES (
            parent_id, c."label", c."starting_bankroll_cents", resolved_ceiling,
            false, c."kill_switch_engaged",
            c."started_at", NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
        );

        -- The existing campaign becomes the active-config portfolio.
        UPDATE "paper_campaigns"
           SET "evaluation_campaign_id" = parent_id,
               "portfolio" = resolved_portfolio,
               "portfolio_started_at" = c."started_at"
         WHERE "id" = c."id";

        -- Create the sibling portfolio rows so both engines begin accumulating.
        -- Each sibling opens with the same starting bankroll and high-water mark;
        -- an opening_balance ledger entry keeps the running-total invariant true
        -- per portfolio. Hybrid is created only when a mixed selection exists.
        INSERT INTO "paper_campaigns" (
            "id", "label", "starting_bankroll_cents", "autonomy_enabled",
            "high_water_mark_cents", "high_water_mark_at", "started_at",
            "created_at", "updated_at",
            "evaluation_campaign_id", "portfolio", "portfolio_started_at"
        )
        SELECT
            gen_random_uuid()::text, c."label", c."starting_bankroll_cents", false,
            c."starting_bankroll_cents", c."started_at", c."started_at",
            CURRENT_TIMESTAMP, CURRENT_TIMESTAMP,
            parent_id, p.portfolio, c."started_at"
        FROM (
            SELECT unnest(ARRAY['baseline','simulation','hybrid']::"PaperPortfolio"[]) AS portfolio
        ) p
        WHERE p.portfolio <> resolved_portfolio
          AND (p.portfolio <> 'hybrid' OR resolved_portfolio = 'hybrid' OR distinct_versions > 1);

        -- Opening-balance ledger entry for each newly created sibling portfolio.
        INSERT INTO "paper_ledger_entries" (
            "id", "campaign_id", "kind", "amount_cents", "balance_after_cents",
            "occurred_at", "created_at"
        )
        SELECT
            gen_random_uuid()::text, pc."id", 'opening_balance',
            pc."starting_bankroll_cents", pc."starting_bankroll_cents",
            pc."started_at", CURRENT_TIMESTAMP
        FROM "paper_campaigns" pc
        WHERE pc."evaluation_campaign_id" = parent_id
          AND pc."id" <> c."id";
    END LOOP;
END $$;

-- Backfill Hybrid attribution. A position's source model is its cycle candidate's
-- projection.modelVersion; fall back to the candidate's own recorded model_version,
-- then to a synthetic marker so the column can be made non-null even for orphaned
-- rows (none expected). The candidate column mirrors projection.modelVersion.
UPDATE "paper_cycle_candidates" cc
   SET "source_model_version" = p."model_version"
  FROM "projections" p
 WHERE cc."projection_id" = p."id"
   AND cc."source_model_version" IS NULL;

UPDATE "paper_positions" pp
   SET "source_model_version" = sub.model_version
  FROM (
    SELECT c."position_id" AS position_id,
           COALESCE(
             (SELECT pr."model_version" FROM "projections" pr WHERE pr."id" = c."projection_id"),
             c."source_model_version"
           ) AS model_version
      FROM "paper_cycle_candidates" c
     WHERE c."position_id" IS NOT NULL
  ) sub
 WHERE pp."id" = sub.position_id
   AND pp."source_model_version" IS NULL
   AND sub.model_version IS NOT NULL;

-- Any position still without a source (no linked candidate/projection) is
-- attributed to the unknown marker rather than blocking the non-null tightening.
UPDATE "paper_positions"
   SET "source_model_version" = 'unknown'
 WHERE "source_model_version" IS NULL;

-- Step 4 & 6: tighten the new columns to non-null and add the unique/index.
ALTER TABLE "paper_campaigns"
    ALTER COLUMN "evaluation_campaign_id" SET NOT NULL,
    ALTER COLUMN "portfolio" SET NOT NULL,
    ALTER COLUMN "portfolio_started_at" SET NOT NULL;

ALTER TABLE "paper_positions" ALTER COLUMN "source_model_version" SET NOT NULL;

-- Step 5: the kill switch now lives on the parent; drop the child column.
ALTER TABLE "paper_campaigns" DROP COLUMN "kill_switch_engaged";

-- Step 7: drop the PaperDryRun table (inspection-only records; no Decision/Position).
DROP TABLE "paper_dry_runs";

-- AddForeignKey
ALTER TABLE "paper_campaigns"
    ADD CONSTRAINT "paper_campaigns_evaluation_campaign_id_fkey"
    FOREIGN KEY ("evaluation_campaign_id") REFERENCES "paper_evaluation_campaigns"("id")
    ON DELETE RESTRICT ON UPDATE CASCADE;

-- CreateIndex
CREATE INDEX "paper_campaigns_evaluation_campaign_id_idx" ON "paper_campaigns"("evaluation_campaign_id");

-- CreateIndex
CREATE UNIQUE INDEX "paper_campaigns_evaluation_campaign_id_portfolio_key" ON "paper_campaigns"("evaluation_campaign_id", "portfolio");
